The Refractive GI (Rt) algorithm! It's a popular method for simulating global illumination in computer graphics. Here's a simplified pseudocode implementation, including refraction:
```python
// Input: Scene, Camera, Light, Material (with refractive index, nu)

// Step 1: Prepare uniforms
uniform vec3 camPos; // Camera position
uniform vec3 lightPos; // Light position
uniform float nu; // Refractive index of the material

// Step 2: Cast rays from each camera sample
for each CCD sample (s) {
  // Ray direction
  vec3 dir = camera_direction(s);

  // Ray origin
  vec3 org = camPos + dir * s.distance;

  // Ray phase function (含 fresnel term)
  float phase = refractive_phase(dir, nu);

  // Step 3: Recursively traverse the scene (Rt algorithm)
  color Calculate_GI(Ray org, dir, nu, lightPos) {
    // Compute GI term
    float gi = 0;
    for each intersection (i) between org and the scene {
      // Hit material
      Material hit_mat = get_material(i);

      // Compute outgoing ray direction
      vec3 out_dir = hit_mat.refract(dir, nu);

      // Recursively traverse the scene
      color gi_term = Calculate_GI(org + i.distance * out_dir, out_dir, hit_mat.nu, lightPos);

      // Accumulate GI term
      gi += gi_term * phase * hit_mat.roughness;
    }

    return gi;
  }

  // Step 4: Integrate over all samples
  color final_gi = 0;
  for each CCD sample (s) {
    final_gi += Calculate_GI(org, dir, nu, lightPos) * s.weight;
  }
}
```
